// src/App.js
import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import HomePage from './components/homepage'; 
import TicketForm from './components/TicketForm'; 
import TicketList from './components/TicketList'; 

const ServiceRequestPage = () => {
  const [tickets, setTickets] = useState([]);

  // Handle ticket submission
  const handleTicketSubmit = (newTicket) => {
    setTickets([...tickets, newTicket]);
  };

  return (
    <div style={{ textAlign: 'center', marginTop: '50px' }}>
      <h1>Submit Your Ticket</h1>
      <TicketForm onSubmit={handleTicketSubmit} />
    </div>
  );
};

const ViewTicketsPage = () => {
  const [tickets] = useState([
    {
      title: "Sample Ticket",
      description: "This is a sample ticket description.",
      status: "Approved",
      id: 1,
    },
  ]);

  return (
    <div style={{ textAlign: 'center', marginTop: '50px' }}>
      <h1>View Submitted Tickets</h1>
      <TicketList tickets={tickets} />
    </div>
  );
};

const App = () => {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/submit-ticket" element={<ServiceRequestPage />} />
        <Route path="/view-tickets" element={<ViewTicketsPage />} />
      </Routes>
    </Router>
  );
};

export default App;
